A possible short term solution is goto https://github.com/algolia/algoliasearch-client-javascript. Here is an example of a angular 4 component using angular material autocomplete in typescript...

```ts
import { Component, OnInit } from "@angular/core";
import { FormControl } from "@angular/forms";

// dirty way to get require to work, only for example purposes
declare var require: any;

// import the algoria library and put in your algolia ids and keys
const algoliasearch = require("algoliasearch");
const client = algoliasearch("appId", "apiKey");

@Component({
  selector: "app-op70",
  template: `
  <md-input-container>
    <input mdInput  [mdAutocomplete]="auto" [formControl]="itemsCtrl" (ngModelChange)="check($event)" >
  </md-input-container>
  <md-autocomplete #auto="mdAutocomplete">
    <md-option *ngFor="let item of data" [value]="item" >
      {{item|json}}
    </md-option>
  </md-autocomplete>
  `,
  styleUrls: ["./op70.component.css"]
})
export class Op70Component implements OnInit {
  index: any;
  data: Array<string>;
  itemsCtrl: FormControl;
  constructor() {
    // set up the reference to the index in algolia
    this.index = client.initIndex("getstarted_actors");

    // set up the material design autocomplete
    this.itemsCtrl = new FormControl();
  }

  ngOnInit() {}

  check(val) {
    // take the val from the material design input and send it to algolia and use the response
    // to update the options.
    this.index.search(val).then(res => {
      this.data = res.hits;
    });
  }
}
```
